<?php $canRegister=($capabilities['inventory.adjust']??false)||($capabilities['inventory.initial']??false)||($capabilities['inventory.correct']??false); $filtered=$q!==''||$status!=='all'; $inventorySection='balances'; require dirname(__DIR__,2).'/components/admin/inventory-nav.php'; ?>
<div class="inventory-workspace"><section class="admin-page-head inventory-page-head"><div><p class="admin-kicker">INVENTARIO</p><h1>Existencias por sucursal</h1><p>Consulta las cantidades por producto y sucursal, revisa mínimos y registra ajustes con su motivo.</p></div><div class="admin-head-actions"><a class="admin-secondary-button" href="/admin/inventory/movements">Movimientos</a><?php if($canRegister):?><a class="admin-primary-button" data-admin-form-link href="/admin/inventory/adjustments">+ Registrar movimiento</a><?php endif?></div></section>
<section class="inventory-guide" aria-label="Cómo leer las existencias"><div><span class="inventory-guide-icon" aria-hidden="true">01</span><div><h2>Existencia física</h2><p>Unidades registradas en la sucursal.</p></div></div><div><span class="inventory-guide-icon" aria-hidden="true">02</span><div><h2>Cantidad apartada</h2><p>Unidades reservadas para operaciones pendientes.</p></div></div><div><span class="inventory-guide-icon" aria-hidden="true">03</span><div><h2>Disponible</h2><p>Existencia física menos cantidad apartada.</p></div></div></section>
<section class="admin-panel inventory-filters"><header><h2>Buscar existencias</h2><p>Localiza un producto y revisa su disponibilidad en cada sucursal.</p></header><form class="admin-filter-bar admin-inventory-filter" method="get" action="/admin/inventory"><label class="admin-field"><span>Buscar</span><input type="search" name="q" maxlength="120" value="<?= e($q) ?>" placeholder="Producto, variante o SKU"></label><label class="admin-field"><span>Sucursal</span><select name="branch_id"><?php if($allBranches??false):?><option value="">Todas las sucursales</option><?php endif?><?php foreach($branches as$b):?><option value="<?= e($b['id']) ?>" <?= $branchId===(int)$b['id']?'selected':'' ?>><?= e($b['name']) ?></option><?php endforeach?></select></label><label class="admin-field"><span>Estado</span><select name="status"><option value="all">Todos</option><option value="low" <?= $status==='low'?'selected':'' ?>>En mínimo</option><option value="out" <?= $status==='out'?'selected':'' ?>>Agotados</option><option value="uninitialized" <?= $status==='uninitialized'?'selected':'' ?>>Sin inicializar</option></select></label><div class="inventory-filter-actions"><button class="admin-secondary-button">Aplicar filtros</button><?php if($filtered||$branchId!==null):?><a class="inventory-text-link" href="/admin/inventory">Limpiar</a><?php endif?></div></form></section>
<section class="admin-panel admin-table-panel inventory-directory"><header class="inventory-directory-heading"><div><h2>Existencias registradas</h2><p>Disponibilidad y mínimo de cada variante por sucursal.</p></div><span class="inventory-page-count"><?= e(count($page->items)) ?> en esta página</span></header><?php if($page->items===[]):?><div class="inventory-empty"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m12 3 9 5v8l-9 5-9-5V8l9-5Zm0 9 9-4M12 12 3 8m9 4v9M7.5 5.5l9 5"/></svg><h3><?= $filtered?'Sin coincidencias':'Aún no hay existencias registradas' ?></h3><p><?= $filtered?'Prueba con otro producto, SKU o estado, o limpia los filtros para ampliar la búsqueda.':'Comienza con un conteo real. Registra la existencia inicial de una variante en su sucursal para consultar aquí su disponibilidad.' ?></p><div class="inventory-empty-actions"><?php if($filtered):?><a class="admin-secondary-button" href="/admin/inventory">Limpiar filtros</a><?php elseif($canRegister):?><a class="admin-primary-button" data-admin-form-link href="/admin/inventory/adjustments<?= ($capabilities['inventory.initial']??false)?'?type=initial':'' ?>"><?= ($capabilities['inventory.initial']??false)?'Registrar existencia inicial':'Registrar movimiento' ?></a><?php endif?></div></div><?php else:?><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Variante</th><th>Sucursal</th><th>Física</th><th>Apartada</th><th>Disponible</th><th>Mínimo</th><th>Acciones</th></tr></thead><tbody><?php foreach($page->items as$row):?><tr><td><div><strong><?= e($row['product_name']) ?></strong><small><?= e($row['sku'].' · '.$row['variant_name']) ?></small></div></td><td><?= e($row['branch_name']) ?></td><td><?= e($row['physical_quantity'].' '.$row['symbol']) ?></td><td><?= e($row['reserved_quantity'].' '.$row['symbol']) ?></td><td><div><strong><?= e($row['available_quantity'].' '.$row['symbol']) ?></strong><?php if((int)$row['is_low']===1):?><small class="admin-stock-warning">Requiere revisión</small><?php endif?></div></td><td><?= $row['minimum_quantity']===null?'Sin configurar':e($row['minimum_quantity'].' '.$row['symbol']) ?></td><td class="admin-actions"><a class="admin-secondary-button" data-admin-form-link href="/admin/inventory/movements?branch_id=<?= e($row['branch_id']) ?>&variant_id=<?= e($row['variant_id']) ?>">Historial</a><?php if($capabilities['inventory.thresholds']??false):?><button type="button" class="admin-quiet-button" data-inventory-minimum="minimum-<?= e($row['branch_id'].'-'.$row['variant_id']) ?>">Configurar mínimo</button><template id="minimum-<?= e($row['branch_id'].'-'.$row['variant_id']) ?>"><section class="inventory-editor"><h1>Configurar existencia mínima</h1><p class="inventory-editor-copy"><?= e($row['product_name'].' · '.$row['sku'].' · '.$row['branch_name']) ?></p><form class="admin-form" method="post" action="/admin/inventory/thresholds"><input type="hidden" name="_token" value="<?= e($csrf) ?>"><input type="hidden" name="branch_id" value="<?= e($row['branch_id']) ?>"><input type="hidden" name="variant_id" value="<?= e($row['variant_id']) ?>"><label class="admin-field"><span>Existencia mínima</span><input name="minimum_quantity" inputmode="decimal" required value="<?= e($row['minimum_quantity']??'0') ?>"></label><p class="inventory-note">Este valor ayuda a identificar existencias que requieren revisión. No modifica el saldo físico.</p><div class="admin-head-actions"><a class="admin-secondary-button" data-admin-modal-cancel href="/admin/inventory">Cancelar</a><button class="admin-primary-button">Guardar mínimo</button></div></form></section></template><?php endif?></td></tr><?php endforeach?></tbody></table></div><?php endif?></section>

<?php if($page->offset>0||$page->hasMore):?><nav class="admin-pagination" aria-label="Páginas de existencias"><?php if($page->offset>0):?><a href="?<?= e(http_build_query(['q'=>$q,'branch_id'=>$branchId,'status'=>$status,'offset'=>max(0,$page->offset-25)])) ?>">Anterior</a><?php endif?><?php if($page->hasMore):?><a href="?<?= e(http_build_query(['q'=>$q,'branch_id'=>$branchId,'status'=>$status,'offset'=>$page->offset+25])) ?>">Siguiente</a><?php endif?></nav><?php endif?></div>
